"text": "// SPDX-License-Identifier: Apache-2.0
// ABOUTME: Closes one accepted disposable handoff through the candidate MCP path, then audits its dashboard readback.
// ABOUTME: Close intent is durable before dispatch; audit-only never starts a server, closes, registers or uploads.
const fs = require('node:fs');
const path = require('node:path');
const os = require('node:os');
const assert = require('node:assert/strict');
const crypto = require('node:crypto');
const hash = value => crypto.createHash('sha256').update(value).digest('hex');
const json = file => JSON.parse(fs.readFileSync(file, 'utf8'));
const inside = (root, file) => path.isAbsolute(file) && path.resolve(file).startsWith(path.resolve(root) + path.sep);
function validateScope(setup, accepted, expected) {
  assert(inside(setup.scratchRoot, setup.project), 'Project must remain within scratch');
  assert.equal(expected.projectRoot, setup.project, 'Expected project must equal the accepted scratch project');
  assert(/^[a-f0-9]{64}$/.test(expected.inputHash), 'Expected input seal is required');
  for (const stage of ['claude', 'developer', 'chat']) {
    const rows = accepted.filter(row => row.stage === stage);
    assert.equal(rows.length, 1, 'Exactly one acceptance per stage');
    assert.equal(rows[0].accepted, true, 'All stages must be accepted');
    assert.equal(rows[0].inputHash, expected.inputHash, 'Every stage must share the accepted input seal');
  }
}
function bindRemoteRecords(remote, registered, localProof, localSession) {
  assert.equal(remote.project.slug, registered.dashboard_slug);
  const identity = {};
  for (const key of ['project_id', 'dashboard_project_id', 'dashboard_slug']) {
    const rows = remote.metadata.filter(row => row.key === key);
    assert.equal(rows.length, 1, 'Exactly one returned ' + key + ' is required');
    assert.equal(rows[0].value, registered[key], 'Returned ' + key + ' differs from the accepted record');
    identity[key] = rows[0].value;
  }
  assert(localProof.decision.created_at, 'Local decision creation time is required');
  const decisions = remote.decisions.filter(row => row.id === localProof.decision.id && row.decisionText === localProof.decision.decision_text && row.createdAt === localProof.decision.created_at);
  assert.equal(decisions.length, 1, 'Exactly one returned decision ID/text/creation-time match is required');
  assert(decisions[0].sessionId == null || decisions[0].sessionId === localProof.decision.author_session_id, 'Remote decision author conflicts with local provenance');
  const sessions = remote.sessions.filter(row => row.id === localSession.id && row.status === localSession.status && row.completedAt === localSession.completed_at);
  assert.equal(sessions.length, 1, 'Exactly one returned implementation session ID/status/time match is required');
  return { sourceProjectId: identity.project_id, mirrorProjectId: remote.project.id,
    registeredProjectId: identity.dashboard_project_id, slug: identity.dashboard_slug,
    decision: decisions[0], developerSession: sessions[0],
    remoteDecisionAuthorship: decisions[0].sessionId == null ? 'unavailable' : 'matched' };
}
function validateClose(done, sessionId, stored) {
  assert.equal(done.sessionId, sessionId, 'Close receipt must name the dispatched session');
  assert(done.completedAt && Array.isArray(done.writeFailures) && done.writeFailures.length === 0, 'Unauditable close: stop; never retry');
  assert.equal(stored?.status, 'completed', 'Dispatched session must be durably completed');
  assert.equal(stored.completed_at, done.completedAt, 'Durable completion must equal the close receipt');
}
async function main(argv) {
  if (!['--execute', '--audit-only'].includes(argv[0]) || argv.length !== 3)
    return { preparedOnly: true, usage: '--execute SETUP EXPECTED | --audit-only SETUP EXPECTED', outwardCalls: 0 };
  const [mode, setupPath, expectedPath] = argv;
  const auditOnly = mode === '--audit-only', setup = json(setupPath), expected = json(expectedPath);
  const accepted = ['claude', 'developer', 'chat'].map(stage => json(path.join(setup.receipts, stage + '-accepted.json')));
  validateScope(setup, accepted, expected);
  const current = JSON.parse(require('node:child_process').execFileSync(process.execPath,
    [path.join(__dirname, 's99-m08-run.cjs'), 'validate', setupPath], { encoding: 'utf8', timeout: 60000 }));
  assert.equal(current.inputHash, expected.inputHash, 'Current preparation differs from the accepted input seal');
  assert(inside(fs.realpathSync(os.tmpdir()), fs.realpathSync(setup.scratchRoot)) && /^reasonbook-s99-m08-/.test(path.basename(setup.scratchRoot)));
  for (const file of [setup.project, setup.processHome, setup.configDir, setup.receipts, setup.arms.developer.packageRoot])
    assert(inside(setup.scratchRoot, fs.realpathSync(file)), 'Resolved path escaped scratch');
  assert.equal(setup.configDir, path.join(setup.processHome, '.config/rbook'));
  const preflight = json(path.join(setup.receipts, 'launcher-preflight.json'));
  assert(preflight.success && preflight.inputHash === expected.inputHash, 'Matching preflight required');
  const { packedCandidate, verifyRuntimeBuild, verifyTranscriptReceipt } = require('./s99-m08-integrity.cjs');
  const packed = packedCandidate(setup.candidate.tarball, setup.candidate.tarballSha256);
  const packageRoot = setup.arms.developer.packageRoot;
  verifyRuntimeBuild(packageRoot, packed.build);
  assert.deepEqual(json(path.join(packageRoot, 'package.json')), packed.package);
  const ledger = fs.readFileSync(path.join(__dirname, 's99-m08-model-runs.jsonl'), 'utf8').trim().split('\n').map(JSON.parse);
  const scenarios = json(path.join(__dirname, 's99-m08-scenarios.json'));
  for (const row of accepted) {
    assert(inside(setup.receipts, fs.realpathSync(row.transcript)));
    verifyTranscriptReceipt(row, ledger.find(x => x.event === 'start' && x.number === row.runNumber), ledger.find(x => x.event === 'exit' && x.number === row.runNumber), hash(fs.readFileSync(row.transcript)));
    for (const check of scenarios.stages[row.stage].acceptance) assert.equal(row.checks[check], true);
  }
  const env = { PATH: process.env.PATH, HOME: setup.processHome, RBOOK_CONFIG_DIR: setup.configDir,
    RBOOK_CHECKPOINT_SYNC: 'on', RBOOK_OFFLINE_EMBEDDINGS: '1', RBOOK_DASHBOARD_URL: 'https://reasonbook.ai', DO_NOT_TRACK: '1' };
  for (const name of Object.keys(process.env)) if (/^(?:CMOS_|RBOOK_)/.test(name)) delete process.env[name];
  Object.assign(process.env, env);
  const candidateRequire = require('node:module').createRequire(path.join(packageRoot, 'package.json'));
  const Database = candidateRequire('better-sqlite3');
  const dbPath = path.join(setup.project, 'rbook/db/rbook.sqlite');
  function read(file, fn) { const db = new Database(file, { readonly: true, fileMustExist: true }); try { return fn(db); } finally { db.close(); } }
  const metadata = () => Object.fromEntries(read(dbPath, db => db.prepare("SELECT key,value FROM metadata WHERE key IN ('project_id','project_name','dashboard_registered','dashboard_slug','dashboard_project_id')").all()).map(row => [row.key, row.value]));
  const registryFile = path.join(setup.configDir, 'project-graph.sqlite');
  const upload = () => read(registryFile, db => db.prepare('SELECT project_id,upload_last_attempt_at,upload_last_outcome,last_synced_at FROM projects WHERE store_path=? AND archived_at IS NULL').get(setup.project));
  const session = id => read(dbPath, db => db.prepare('SELECT id,agent,status,completed_at,captures FROM sessions WHERE id=?').get(id));
  const primary = path.join(setup.receipts, 'dashboard-close.json');
  const receiptPath = auditOnly ? path.join(setup.receipts, 'dashboard-audit-' + Date.now() + '.json') : primary;
  const receipt = { success: false, project: setup.project, candidate: setup.candidate, inputHash: expected.inputHash,
